/*
 * Cold Gravy Interactive - studio splash screen.
 *
 * Drop-in, no dependencies, works offline (the artwork is embedded).
 * Include it as the FIRST <script> inside <body>, before any game script:
 *
 *   <script src="cold-gravy-splash.js"></script>
 *
 * It covers the screen for ~2.2s on every cold launch, then removes itself.
 * Tap to skip after 0.4s. Reduced-motion users get a short static version.
 * Start the game's own intro, music and ads only after it finishes:
 *
 *   ColdGravySplash.done.then(startGame);
 *
 * Generated from cold-gravy-splash.src.js and art.js by build.js - edit those, not the output.
 */
(function () {
  'use strict';

  if (window.ColdGravySplash) return;

  var HOLD_MS = 1100;      // when the fade-out starts (web: shorter, players have already clicked to play)
  var FADE_MS = 300;
  var SKIP_AFTER_MS = 400; // ignore taps before this so a launch tap does not skip it
  var REDUCED_HOLD_MS = 700;

  var reduced = false;
  try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}

  var resolveDone;
  var done = new Promise(function (r) { resolveDone = r; });
  window.ColdGravySplash = { done: done };

  // Pre-rendered layers (WebP made by build.js from art.js). Each image has a 10% margin
  // on every side, so it sits at -10% / 120% of its box.
  var MARK = 'data:image/webp;base64,';
  var WORD = 'data:image/webp;base64,';
  var SWOOSH = 'data:image/webp;base64,';
  var SUB = 'data:image/webp;base64,';
  // Unfiltered, cheap to draw, so these stay live SVG
  var fly = "<svg class=\"cg-fly\" viewBox=\"400 110 160 110\" aria-hidden=\"true\"><g><animateMotion dur=\"1.4s\" repeatCount=\"indefinite\" rotate=\"auto\" path=\"M480 168 C510 128 552 150 532 178 C512 204 452 196 442 170 C432 144 456 132 480 168 Z\"/><g transform=\"rotate(90)\"><ellipse cx=\"-6\" cy=\"-5\" rx=\"5\" ry=\"8\" fill=\"#fff8ec\" stroke=\"#2a1e17\" stroke-width=\"2.5\" transform=\"rotate(-25 -6 -5)\"><animateTransform attributeName=\"transform\" type=\"rotate\" values=\"-25 -6 -5;-55 -6 -5;-25 -6 -5\" dur=\"0.09s\" repeatCount=\"indefinite\"/></ellipse><ellipse cx=\"6\" cy=\"-5\" rx=\"5\" ry=\"8\" fill=\"#fff8ec\" stroke=\"#2a1e17\" stroke-width=\"2.5\" transform=\"rotate(25 6 -5)\"><animateTransform attributeName=\"transform\" type=\"rotate\" values=\"25 6 -5;55 6 -5;25 6 -5\" dur=\"0.09s\" repeatCount=\"indefinite\"/></ellipse><ellipse cx=\"0\" cy=\"2\" rx=\"5.5\" ry=\"7.5\" fill=\"#2a1e17\"/></g></g></svg>";
  var drop = "<svg class=\"cg-drop\" viewBox=\"0 0 20 30\" aria-hidden=\"true\"><path d=\"M10 2 C12 10 18 16 17 22 C16 28 4 28 3 22 C2 16 8 10 10 2 Z\" fill=\"#8a5a2b\" stroke=\"#2a1e17\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/><path d=\"M7 20 q1 -3 3 -4\" stroke=\"#c99257\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\"/></svg>";

  var css = [
    '#cg-splash{position:fixed;inset:0;z-index:2147483647;background:#f3ebdd;display:flex;align-items:center;justify-content:center;',
    '-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent;touch-action:none;transition:opacity ' + FADE_MS + 'ms ease}',
    '#cg-splash.cg-out{opacity:0}',
    // 62vh keeps the logo and wordmark to about 56% of the height on landscape and short screens.
    // In portrait the 78vw and 420px limits still win, so it looks the same there.
    '#cg-splash .cg-wrap{width:min(78vw,420px,62vh);display:flex;flex-direction:column;align-items:center}',
    '#cg-splash .cg-markbox{position:relative;width:100%;aspect-ratio:530/330}',
    '#cg-splash svg{display:block;position:absolute;overflow:visible}',
    '#cg-splash .cg-layer{position:absolute}',
    '#cg-splash .cg-layer img{position:absolute;left:-10%;top:-10%;width:120%;height:120%;display:block;pointer-events:none;-webkit-user-drag:none}',
    // Nothing animates until the artwork is decoded and on screen (the cg-go class), so the
    // entrance is never spent behind a launch screen or a slow first frame.
    '#cg-splash:not(.cg-go) *{animation-play-state:paused!important}',
    '#cg-splash .cg-mark{inset:0;width:100%;height:100%;will-change:transform,opacity;transform-origin:50% 90%;opacity:0;animation:cg-pop 520ms cubic-bezier(.3,1.5,.5,1) 60ms forwards}',
    '#cg-splash .cg-fly{left:66%;top:0;width:30.2%;height:33.3%;opacity:0;animation:cg-fade 300ms ease 450ms forwards}',
    '#cg-splash .cg-drop{left:5.6%;top:57%;width:5%;height:9%;opacity:0;animation:cg-drip 900ms cubic-bezier(.55,0,.9,.5) 700ms 2}',
    '#cg-splash .cg-wordbox{position:relative;width:100%;aspect-ratio:900/270;margin-top:-2%}',
    '#cg-splash .cg-word{inset:0;width:100%;height:100%;opacity:0;will-change:transform,opacity;animation:cg-rise 420ms cubic-bezier(.2,1.3,.5,1) 320ms forwards}',
    '#cg-splash .cg-sub{inset:0;width:100%;height:100%;opacity:0;animation:cg-fade 350ms ease 600ms forwards}',
    // The swoosh draws left to right. A clip wipe over the image stands in for the old stroke-dash
    // draw: the path runs from 21.7% to 79.3% of the image width, margins included.
    '#cg-splash .cg-swoosh{inset:0;width:100%;height:100%}',
    '#cg-splash .cg-swoosh img{clip-path:inset(0 78.3% 0 0);animation:cg-draw 420ms ease-out 660ms forwards}',
    '@keyframes cg-pop{0%{opacity:0;transform:scale(.82) rotate(-5deg)}60%{opacity:1;transform:scale(1.05) rotate(2deg)}100%{opacity:1;transform:none}}',
    '@keyframes cg-rise{0%{opacity:0;transform:translateY(14%)}100%{opacity:1;transform:none}}',
    '@keyframes cg-fade{to{opacity:1}}',
    '@keyframes cg-draw{to{clip-path:inset(0 20% 0 0)}}',
    '@keyframes cg-drip{0%{opacity:0;transform:translateY(0) scaleY(.4)}15%{opacity:1;transform:translateY(0) scaleY(1)}35%{transform:translateY(5%) scaleY(1.15)}100%{opacity:0;transform:translateY(260%) scaleY(1)}}',
    '#cg-splash.cg-reduced *{animation-duration:1ms!important;animation-delay:0ms!important;animation-iteration-count:1!important}',
    '#cg-splash.cg-reduced .cg-drop{display:none}'
  ].join('');

  function layer(cls, src) {
    return '<div class="cg-layer ' + cls + '" aria-hidden="true"><img alt="" draggable="false" src="' + src + '"></div>';
  }

  function mount() {
    var style = document.createElement('style');
    style.id = 'cg-splash-style';
    style.textContent = css;
    document.head.appendChild(style);

    var root = document.createElement('div');
    root.id = 'cg-splash';
    root.setAttribute('role', 'img');
    root.setAttribute('aria-label', 'Cold Gravy Interactive');
    if (reduced) root.className = 'cg-reduced';
    root.innerHTML =
      '<div class="cg-wrap">' +
        '<div class="cg-markbox">' + layer('cg-mark', MARK) + drop + fly + '</div>' +
        '<div class="cg-wordbox">' + layer('cg-swoosh', SWOOSH) + layer('cg-word', WORD) + layer('cg-sub', SUB) + '</div>' +
      '</div>';
    document.body.appendChild(root);

    var start = Date.now();
    var finished = false;

    function finish() {
      if (finished) return;
      finished = true;
      root.classList.add('cg-out');
      setTimeout(function () {
        if (root.parentNode) root.parentNode.removeChild(root);
        if (style.parentNode) style.parentNode.removeChild(style);
        resolveDone();
      }, FADE_MS);
    }

    // Swallow every touch so nothing reaches the game underneath.
    function block(e) {
      e.preventDefault();
      e.stopPropagation();
      if (e.type === 'pointerdown' && Date.now() - start >= SKIP_AFTER_MS) finish();
    }
    ['pointerdown', 'pointerup', 'click', 'touchstart', 'touchend', 'mousedown', 'mouseup'].forEach(function (t) {
      root.addEventListener(t, block, { passive: false });
    });

    // Start the entrance and the hold clock only when the artwork is decoded and a frame has been
    // drawn, so the full hold is spent with the logo on screen.
    // The fallback starts it anyway if frames never arrive (for example a launch in the background).
    // It waits 6 s because an Android launch screen can hold back the first frame for several seconds on a slow phone.
    var begun = false;
    function begin() {
      if (begun) return;
      begun = true;
      start = Date.now();
      root.classList.add('cg-go');
      setTimeout(finish, reduced ? REDUCED_HOLD_MS : HOLD_MS);
    }
    function painted() {
      var raf = window.requestAnimationFrame;
      if (raf) raf(function () { raf(begin); });
    }
    var imgs = root.getElementsByTagName('img');
    var waits = [];
    for (var i = 0; i < imgs.length; i++) {
      if (imgs[i].decode) waits.push(imgs[i].decode().catch(function () {}));
    }
    Promise.all(waits).then(painted, painted);
    setTimeout(begin, 6000);
  }

  if (document.body) mount();
  else document.addEventListener('DOMContentLoaded', mount);
})();
